--- docs/copilot-chat-analysis.html	
+++ docs/copilot-chat-analysis.html	
@@ -0,0 +1,129 @@
+<!DOCTYPE html>
+<html lang="ja">
+<head>
+<meta charset="UTF-8">
+<meta name="viewport" content="width=device-width, initial-scale=1.0">
+<title>GitHub Copilot 活用分析レポート — freecell-classic</title>
+<style>
+:root {
+  --primary: #5865f2; --text: #1e293b; --muted: #64748b;
+  --bg: #f1f5f9; --panel: #ffffff; --border: #e2e8f0;
+}
+* { box-sizing: border-box; }
+body {
+  margin: 0; padding: 2rem 1rem; background: var(--bg); color: var(--text);
+  font-family: "Hiragino Kaku Gothic ProN", "Noto Sans JP", Meiryo, sans-serif;
+  line-height: 1.7;
+}
+.wrap { max-width: 1000px; margin: 0 auto; }
+header.report { margin-bottom: 2rem; }
+h1 { font-size: 1.7rem; margin: 0 0 .3rem; }
+header.report p { color: var(--muted); margin: 0; }
+section.panel {
+  background: var(--panel); border: 1px solid var(--border); border-radius: 10px;
+  padding: 1.4rem 1.6rem; margin-bottom: 1.6rem;
+}
+h2 { font-size: 1.15rem; border-left: 4px solid var(--primary); padding-left: .6rem; margin: 0 0 1rem; }
+h3 { font-size: 1rem; margin: 1.2rem 0 .5rem; }
+.cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: .8rem; }
+.card { background: var(--panel); border: 1px solid var(--border); border-radius: 10px; padding: .9rem 1.1rem; }
+.card-title { font-size: .78rem; color: var(--muted); }
+.card-value { font-size: 1.45rem; font-weight: 700; color: var(--primary); }
+.card-note { font-size: .75rem; color: var(--muted); }
+.chart { width: 100%; height: auto; }
+.legend { display: flex; gap: 1.2rem; font-size: .8rem; color: var(--muted); margin: .2rem 0 .6rem; }
+.legend span::before {
+  content: ""; display: inline-block; width: 10px; height: 10px; border-radius: 2px;
+  margin-right: .35em; vertical-align: baseline; background: var(--c);
+}
+table { border-collapse: collapse; width: 100%; font-size: .82rem; }
+th, td { padding: .38rem .55rem; border-bottom: 1px solid var(--border); text-align: left; vertical-align: top; }
+th { color: var(--muted); font-weight: 600; white-space: nowrap; }
+td.num { text-align: right; }
+.nowrap { white-space: nowrap; }
+.muted { color: var(--muted); }
+.note { font-size: .78rem; color: var(--muted); }
+ul.insights li { margin-bottom: .45rem; }
+footer { text-align: center; font-size: .75rem; color: var(--muted); padding: 1rem 0 2rem; }
+@media print { body { background: #fff; padding: 0; } section.panel { break-inside: avoid; } }
+</style>
+</head>
+<body>
+<div class="wrap">
+<header class="report">
+<h1>GitHub Copilot 活用分析レポート</h1>
+<p>freecell-classic 開発における Copilot Chat 履歴の定量分析 | 生成日: 2026-08-26</p>
+</header>
+
